import requests
import json

url = "https://partner.shopeemobile.com/api/v2/order/set_note?access_token=access_token&partner_id=partner_id&shop_id=shop_id&sign=sign&timestamp=timestamp"

payload=json.dumps({
  "note": "Thank you",
  "order_sn": "201224EM1FMFG1"
})
headers = {
  'Content-Type': 'application/json'
}
response = requests.request("POST",url,headers=headers, data=payload, allow_redirects=False)

print(response.text)

